function setLanguage(value){if(!['de','en'].includes(value)||value===lang)return;lang=value;try{localStorage.setItem('al-lang',lang);const url=new URL(location.href);url.searchParams.set('lang',lang);history.replaceState(null,'',url)}catch(e){}render();document.querySelector(`[data-lang="${lang}"]`).focus({preventScroll:true})}
function updateTheme(){const dark=document.documentElement.dataset.theme==='dark';const b=document.querySelector('#theme-toggle');b.innerHTML=icon(dark?'sun':'moon');b.setAttribute('aria-label',dark?copy[lang].light:copy[lang].theme);b.title=dark?copy[lang].light:copy[lang].theme}
function toggleTheme(){const value=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=value;try{localStorage.setItem('al-theme',value)}catch(e){}updateTheme()}
